module DDR3_Memory_Interface_Top (
  clk,
  pll_stop,
  memory_clk,
  pll_lock,
  rst_n,
  clk_out,
  ddr_rst,
  init_calib_complete,
  cmd_ready,
  cmd,
  cmd_en,
  addr,
  wr_data_rdy,
  wr_data,
  wr_data_en,
  wr_data_end,
  wr_data_mask,
  rd_data,
  rd_data_valid,
  rd_data_end,
  sr_req,
  ref_req,
  sr_ack,
  ref_ack,
  burst,
  O_ddr_addr,
  O_ddr_ba,
  O_ddr_cs_n,
  O_ddr_ras_n,
  O_ddr_cas_n,
  O_ddr_we_n,
  O_ddr_clk,
  O_ddr_clk_n,
  O_ddr_cke,
  O_ddr_odt,
  O_ddr_reset_n,
  O_ddr_dqm,
  IO_ddr_dq,
  IO_ddr_dqs,
  IO_ddr_dqs_n
)
;
input clk;
output pll_stop;
input memory_clk;
input pll_lock;
input rst_n;
output clk_out;
output ddr_rst;
output init_calib_complete;
output cmd_ready;
input [2:0] cmd;
input cmd_en;
input [28:0] addr;
output wr_data_rdy;
input [255:0] wr_data;
input wr_data_en;
input wr_data_end;
input [31:0] wr_data_mask;
output [255:0] rd_data;
output rd_data_valid;
output rd_data_end;
input sr_req;
input ref_req;
output sr_ack;
output ref_ack;
input burst;
output [14:0] O_ddr_addr;
output [2:0] O_ddr_ba;
output O_ddr_cs_n;
output O_ddr_ras_n;
output O_ddr_cas_n;
output O_ddr_we_n;
output O_ddr_clk;
output O_ddr_clk_n;
output O_ddr_cke;
output O_ddr_odt;
output O_ddr_reset_n;
output [3:0] O_ddr_dqm;
inout [31:0] IO_ddr_dq;
inout [3:0] IO_ddr_dqs;
inout [3:0] IO_ddr_dqs_n;
wire VCC;
wire GND;
  \~GW_DDR3_PHY_MC.DDR3_Memory_Interface_Top  gw3_top (
    .memory_clk(memory_clk),
    .clk(clk),
    .rst_n(rst_n),
    .pll_lock(pll_lock),
    .cmd_en(cmd_en),
    .sr_req(sr_req),
    .wr_data_end(wr_data_end),
    .wr_data_en(wr_data_en),
    .cmd(cmd[2:0]),
    .addr(addr[27:0]),
    .wr_data(wr_data[255:0]),
    .wr_data_mask(wr_data_mask[31:0]),
    .clk_out(clk_out),
    .ddr_rst(ddr_rst),
    .pll_stop(pll_stop),
    .O_ddr_clk(O_ddr_clk),
    .O_ddr_clk_n(O_ddr_clk_n),
    .O_ddr_reset_n(O_ddr_reset_n),
    .O_ddr_cs_n(O_ddr_cs_n),
    .O_ddr_ras_n(O_ddr_ras_n),
    .O_ddr_cas_n(O_ddr_cas_n),
    .O_ddr_we_n(O_ddr_we_n),
    .O_ddr_cke(O_ddr_cke),
    .O_ddr_odt(O_ddr_odt),
    .init_calib_complete(init_calib_complete),
    .rd_data_valid(rd_data_valid),
    .cmd_ready(cmd_ready),
    .ref_ack(ref_ack),
    .sr_ack(sr_ack),
    .wr_data_rdy(wr_data_rdy),
    .O_ddr_dqm(O_ddr_dqm[3:0]),
    .O_ddr_addr(O_ddr_addr[14:0]),
    .O_ddr_ba(O_ddr_ba[2:0]),
    .rd_data(rd_data[255:0]),
    .IO_ddr_dqs(IO_ddr_dqs[3:0]),
    .IO_ddr_dqs_n(IO_ddr_dqs_n[3:0]),
    .IO_ddr_dq(IO_ddr_dq[31:0])
);
  VCC VCC_cZ (
    .V(VCC)
);
  GND GND_cZ (
    .G(GND)
);
